Reusing instantiation

private Seller instantiateSeller(ResultSet rs, Department dep) throws SQLException { Seller obj = new Seller();

obj.setId(rs.getInt("Id"));

obj.setName(rs.getString("Name"));

obj.setEmail(rs.getString("Email"));

obj.setBaseSalary(rs.getDouble("BaseSalary"));

obj.setBirthDate(rs.getDate("BirthDate"));

obj.setDepartment(dep);

return obj;

}

private Department instantiateDepartment(ResultSet rs) throws SQLException { Department dep = new Department(); dep.setId(rs.getInt("DepartmentId")); dep.setName(rs.getString("DepName")); return dep;

}
